private string GetPrintModuleName(int intIndex, DataRow drwSample)
{
    if (intIndex < 1 || intIndex > SUBJECT_NAME_FIELD_LIST.Length)
        return "MD" + intIndex.ToString();

    if (drwSample != null && drwSample.Table.Columns.Contains(SUBJECT_NAME_FIELD_LIST[intIndex - 1]))
    {
        string strName = drwSample[SUBJECT_NAME_FIELD_LIST[intIndex - 1]].ToString();
        if (strName != "")
            return strName;
    }
    return "MD" + intIndex.ToString();
}

