    {
        foreach (DataRow drw in dtbData.Rows)
        {
            if (strTrainingType == "" && drw["TrainingType"].ToString() != "")
                strTrainingType = drw["TrainingType"].ToString();
            if (strCourseName == "" && drw["CourseName"].ToString() != "")
                strCourseName = drw["CourseName"].ToString();

            if (strTrainingType != "" && strCourseName != "")
                break;
        }
    }

    int intYear = DateTime.Now.Year;
    if (intExamDateID != null)
    {
        DataTable dtbExam = SIM_ExamDateService.Table;
        if (dtbExam != null)
        {
            DataRow[] arrRow = dtbExam.Select("ExamDateID = " + intExamDateID.ToString());
            if (arrRow.Length > 0 && arrRow[0][SIM_ExamDate.C_ExamDate] != DBNull.Value)
            {
                try
                {
                    intYear = Convert.ToDateTime(arrRow[0][SIM_ExamDate.C_ExamDate]).Year;
                }
                catch
                {
                }
            }
        }
